module grasshopper(\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] grid_0_0, grid_0_1, grid_0_2, grid_0_3,\n    input [7:0] grid_1_0, grid_1_1, grid_1_2, grid_1_3,\n    input [7:0] grid_2_0, grid_2_1, grid_2_2, grid_2_3,\n    input [7:0] grid_3_0, grid_3_1, grid_3_2, grid_3_3,\n    input [1:0] start_row, start_col,\n    output reg [4:0] max_length,\n    output reg done\n);\n\n    // State definitions\n    localparam [3:0] S_IDLE = 4'd0;\n    localparam [3:0] S_LOAD = 4'd1;\n    localparam [3:0] S_SORT_INIT = 4'd2;\n    localparam [3:0] S_SORT_LOOP = 4'd3;\n    localparam [3:0] S_SORT_COMPARE = 4'd4;\n    localparam [3:0] S_SORT_SWAP = 4'd5;\n    localparam [3:0] S_SORT_NEXT = 4'd6;\n    localparam [3:0] S_DP_INIT = 4'd7;\n    localparam [3:0] S_DP_OUTER = 4'd8;\n    localparam [3:0] S_DP_INNER = 4'd9;\n    localparam [3:0] S_DP_UPDATE = 4'd10;\n    localparam [3:0] S_DP_NEXT_J = 4'd11;\n    localparam [3:0] S_DP_NEXT_K = 4'd12;\n    localparam [3:0] S_RESULT = 4'd13;\n    localparam [3:0] S_DONE = 4'd14;\n\n    // Registers\n    reg [3:0] state;\n    reg [3:0] pass, i, k, j;\n    reg [7:0] petal [0:15];\n    reg [3:0] idx [0:15];\n    reg [4:0] dp [0:15];\n    reg [4:0] max_length_reg;\n    reg done_reg;\n\n    // Temporary registers\n    reg [7:0] temp_petal;\n    reg [3:0] temp_idx;\n    reg [4:0] temp_dp;\n\n    // Coordinates and move calculation\n    reg [1:0] r_i, c_i, r_j, c_j;\n    reg [1:0] diff_r, diff_c;\n    reg move_allowed;\n\n    // Combinational logic for move check\n    always @(*) begin\n        r_i = idx[i][3:2];\n        c_i = idx[i][1:0];\n        r_j = idx[j][3:2];\n        c_j = idx[j][1:0];\n        \n        if (r_i > r_j) diff_r = r_i - r_j; else diff_r = r_j - r_i;\n        if (c_i > c_j) diff_c = c_i - c_j; else diff_c = c_j - c_i;\n        \n        move_allowed = ((diff_r == 1 && diff_c >= 2) || (diff_c == 1 && diff_r >= 2));\n    end\n\n    // Main state machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= S_IDLE;\n            done <= 1'b0;\n            max_length <= 5'd0;\n            pass <= 4'd0;\n            i <= 4'd0;\n            k <= 4'd0;\n            j <= 4'd0;\n            done_reg <= 1'b0;\n        end else begin\n            case (state)\n                S_IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= S_LOAD;\n                    end\n                end\n                \n                S_LOAD: begin\n                    petal[0] <= grid_0_0;\n                    petal[1] <= grid_0_1;\n                    petal[2] <= grid_0_2;\n                    petal[3] <= grid_0_3;\n                    petal[4] <= grid_1_0;\n                    petal[5] <= grid_1_1;\n                    petal[6] <= grid_1_2;\n                    petal[7] <= grid_1_3;\n                    petal[8] <= grid_2_0;\n                    petal[9] <= grid_2_1;\n                    petal[10] <= grid_2_2;\n                    petal[11] <= grid_2_3;\n                    petal[12] <= grid_3_0;\n                    petal[13] <= grid_3_1;\n                    petal[14] <= grid_3_2;\n                    petal[15] <= grid_3_3;\n                    \n                    idx[0] <= 4'd0;\n                    idx[1] <= 4'd1;\n                    idx[2] <= 4'd2;\n                    idx[3] <= 4'd3;\n                    idx[4] <= 4'd4;\n                    idx[5] <= 4'd5;\n                    idx[6] <= 4'd6;\n                    idx[7] <= 4'd7;\n                    idx[8] <= 4'd8;\n                    idx[9] <= 4'd9;\n                    idx[10] <= 4'd10;\n                    idx[11] <= 4'd11;\n                    idx[12] <= 4'd12;\n                    idx[13] <= 4'd13;\n                    idx[14] <= 4'd14;\n                    idx[15] <= 4'd15;\n                    \n                    state <= S_SORT_INIT;\n                end\n                \n                S_SORT_INIT: begin\n                    pass <= 4'd0;\n                    i <= 4'd0;\n                    state <= S_SORT_LOOP;\n                end\n                \n                S_SORT_LOOP: begin\n                    if (i < 14 - pass) begin\n                        state <= S_SORT_COMPARE;\n                    end else begin\n                        pass <= pass + 4'd1;\n                        i <= 4'd0;\n                        if (pass >= 15) begin\n                            state <= S_DP_INIT;\n                        end else begin\n                            state <= S_SORT_LOOP;\n                        end\n                    end\n                end\n                \n                S_SORT_COMPARE: begin\n                    if (petal[i] < petal[i + 1]) begin\n                        state <= S_SORT_SWAP;\n                    end else begin\n                        state <= S_SORT_NEXT;\n                    end\n                end\n                \n                S_SORT_SWAP: begin\n                    temp_petal <= petal[i];\n                    petal[i] <= petal[i + 1];\n                    petal[i + 1] <= temp_petal;\n                    \n                    temp_idx <= idx[i];\n                    idx[i] <= idx[i + 1];\n                    idx[i + 1] <= temp_idx;\n                    \n                    state <= S_SORT_NEXT;\n                end\n                \n                S_SORT_NEXT: begin\n                    i <= i + 4'd1;\n                    state <= S_SORT_LOOP;\n                end\n                \n                S_DP_INIT: begin\n                    dp[0] <= 5'd1;\n                    dp[1] <= 5'd1;\n                    dp[2] <= 5'd1;\n                    dp[3] <= 5'd1;\n                    dp[4] <= 5'd1;\n                    dp[5] <= 5'd1;\n                    dp[6] <= 5'd1;\n                    dp[7] <= 5'd1;\n                    dp[8] <= 5'd1;\n                    dp[9] <= 5'd1;\n                    dp[10] <= 5'd1;\n                    dp[11] <= 5'd1;\n                    dp[12] <= 5'd1;\n                    dp[13] <= 5'd1;\n                    dp[14] <= 5'd1;\n                    dp[15] <= 5'd1;\n                    \n                    k <= 4'd0;\n                    state <= S_DP_OUTER;\n                end\n                \n                S_DP_OUTER: begin\n                    if (k < 16) begin\n                        j <= 4'd0;\n                        state <= S_DP_INNER;\n                    end else begin\n                        state <= S_RESULT;\n                    end\n                end\n                \n                S_DP_INNER: begin\n                    if (j < 16) begin\n                        state <= S_DP_UPDATE;\n                    end else begin\n                        state <= S_DP_NEXT_K;\n                    end\n                end\n                \n                S_DP_UPDATE: begin\n                    if (move_allowed && (petal[j] > petal[idx[k]])) begin\n                        if (dp[idx[k]] < dp[j] + 1) begin\n                            dp[idx[k]] <= dp[j] + 1;\n                        end\n                    end\n                    state <= S_DP_NEXT_J;\n                end\n                \n                S_DP_NEXT_J: begin\n                    j <= j + 4'd1;\n                    state <= S_DP_INNER;\n                end\n                \n                S_DP_NEXT_K: begin\n                    k <= k + 4'd1;\n                    state <= S_DP_OUTER;\n                end\n                \n                S_RESULT: begin\n                    max_length_reg <= dp[{start_row, start_col}];\n                    state <= S_DONE;\n                end\n                \n                S_DONE: begin\n                    max_length <= max_length_reg;\n                    done <= 1'b1;\n                    if (!start) begin\n                        state <= S_IDLE;\n                    end\n                end\n                \n                default: state <= S_IDLE;\n            endcase\n        end\n    end\n\nendmodule